mapper.select:
/*부모교육 서비스 통계 selectParntsEduSrvcList - Lee.Seoung.Jae */
SELECT CASE GROUPING(A.LINK_TYPE_SE_CD) WHEN 1 THEN '합계' ELSE CASE A.LINK_TYPE_SE_CD WHEN '07' THEN '학교 진단' WHEN '08' THEN '유관기관 진단' WHEN '09' THEN '센터 진단' WHEN '10' THEN '미연계(직접등록)' WHEN '11' THEN '미등록 사례지원' END END AS LINK_SE /*연계구분*/ , A.LINK_TYPE_SE_CD , SUM(NVL(SCHBOY_MAN, 0)) AS SCHBOY_MAN , SUM(NVL(SCHBOY_WOMAN, 0)) AS SCHBOY_WOMAN , SUM(NVL(SCHBOY_NO_ANSWER, 0)) AS SCHBOY_NO_ANSWER , SUM(NVL(SCHBOY_SUM, 0)) AS SCHBOY_SUM , SUM(NVL(MSKLSD_MAN, 0)) AS MSKLSD_MAN , SUM(NVL(MSKLSD_WOMAN, 0)) AS MSKLSD_WOMAN , SUM(NVL(MSKLSD_NO_ANSWER, 0)) AS MSKLSD_NO_ANSWER , SUM(NVL(MSKLSD_SUM, 0)) AS MSKLSD_SUM , SUM(NVL(HGSCHS_MAN, 0)) AS HGSCHS_MAN , SUM(NVL(HGSCHS_WOMAN, 0)) AS HGSCHS_WOMAN , SUM(NVL(HGSCHS_NO_ANSWER, 0)) AS HGSCHS_NO_ANSWER , SUM(NVL(HGSCHS_SUM, 0)) AS HGSCHS_SUM , SUM(NVL(SUM_MAN, 0)) AS SUM_MAN , SUM(NVL(SUM_WOMAN, 0)) AS SUM_WOMAN , SUM(NVL(SUM_NO_ANSWER, 0)) AS SUM_NO_ANSWER FROM ( SELECT '07' AS LINK_TYPE_SE_CD FROM DUAL UNION SELECT '08' AS LINK_TYPE_SE_CD FROM DUAL UNION SELECT '09' AS LINK_TYPE_SE_CD FROM DUAL UNION SELECT '10' AS LINK_TYPE_SE_CD FROM DUAL UNION SELECT '11' AS LINK_TYPE_SE_CD FROM DUAL ) A LEFT JOIN (SELECT * FROM (SELECT LINK_TYPE_SE_CD , SCHBOY_MAN , SCHBOY_WOMAN , SCHBOY_NO_ANSWER , SCHBOY_SUM , MSKLSD_MAN , MSKLSD_WOMAN , MSKLSD_NO_ANSWER , MSKLSD_SUM , HGSCHS_MAN , HGSCHS_WOMAN , HGSCHS_NO_ANSWER , HGSCHS_SUM , NVL(SCHBOY_MAN, 0) + NVL(MSKLSD_MAN, 0) + NVL(HGSCHS_MAN, 0) AS SUM_MAN , NVL(SCHBOY_WOMAN, 0) + NVL(MSKLSD_WOMAN, 0) + NVL(HGSCHS_WOMAN, 0) AS SUM_WOMAN , NVL(SCHBOY_NO_ANSWER, 0) + NVL(MSKLSD_NO_ANSWER, 0) + NVL(HGSCHS_NO_ANSWER, 0) AS SUM_NO_ANSWER FROM ( SELECT A.LINK_TYPE_SE_CD AS LINK_TYPE_SE_CD , COUNT(
DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '1' AND A.SXDC_SE_CD = 'M' THEN A.TRPR_INFO_NO END ) AS SCHBOY_MAN ,COUNT( DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '1' AND A.SXDC_SE_CD = 'F' THEN A.TRPR_INFO_NO END ) AS SCHBOY_WOMAN , COUNT( DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '1' AND A.SXDC_SE_CD = 'X' THEN A.TRPR_INFO_NO END ) AS SCHBOY_NO_ANSWER , COUNT( DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '1' THEN A.TRPR_INFO_NO END ) AS SCHBOY_SUM , COUNT( DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '2' AND A.SXDC_SE_CD = 'M' THEN A.TRPR_INFO_NO END ) AS MSKLSD_MAN , COUNT( DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '2' AND A.SXDC_SE_CD = 'F' THEN A.TRPR_INFO_NO END )AS MSKLSD_WOMAN , COUNT( DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '2' AND A.SXDC_SE_CD = 'X' THEN A.TRPR_INFO_NO END ) AS MSKLSD_NO_ANSWER , COUNT( DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '2' THEN A.TRPR_INFO_NO END ) AS MSKLSD_SUM , COUNT( DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '3' AND A.SXDC_SE_CD = 'M' THEN A.TRPR_INFO_NO END ) AS HGSCHS_MAN , COUNT( DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '3' AND A.SXDC_SE_CD = 'F' THEN A.TRPR_INFO_NO END ) AS HGSCHS_WOMAN , COUNT( DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '3' AND A.SXDC_SE_CD = 'X' THEN A.TRPR_INFO_NO END ) AS HGSCHS_NO_ANSWER , COUNT( DISTINCTCASE WHEN A.MEDIAA_SCHL_SE_CD = '3' THEN A.TRPR_INFO_NO END ) AS HGSCHS_SUM
FROM ACA210 A JOIN ( SELECT RCPT_YMD , RCPT_TRPR_INFO_NO , RCPT_INST_NO , LINK_TYPE_SE_CD , DEL_YN , ROW_NUMBER() OVER(PARTITION BY SRVC_PVSN_RQST_NO ORDER BY RCPT_SN DESC) AS RN FROM SEB420 ) B ON A.TRPR_INFO_NO = B.RCPT_TRPR_INFO_NO AND A.LINK_TYPE_SE_CD = B.LINK_TYPE_SE_CD AND B.DEL_YN = 'N' AND B.RN = 1 JOIN SAA000 T ON T.INST_NO = B.RCPT_INST_NO JOIN ACA200 D ON D.TRPR_INFO_NO = A.TRPR_INFO_NO AND D.DGNSS_EXMN_MNG_NO = A.DGNSS_EXMN_MNG_NO JOIN SEB100 E ON D.CASE_MNG_NO = E.CASE_MNG_NO AND D.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO LEFT JOIN ( SELECT CASE_MNG_NO , CASE_MNG_ODRNO , CASE_PIC_NO , PIC_INST_NO , ROW_NUMBER() OVER(PARTITION BY CASE_MNG_NO, CASE_MNG_ODRNO ORDER BY CASE_MNG_NO, CASE_MNG_ODRNO) AS RN FROM SEB150 ) F0 ON E.CASE_MNG_NO = F0.CASE_MNG_NO AND E.CASE_MNG_ODRNO = F0.CASE_MNG_ODRNO JOIN (SELECT DISTINCT RESRCE_NO , CASE_MNG_NO , CASE_MNG_ODRNO FROM SEB510 ) G ON G.CASE_MNG_NO = E.CASE_MNG_NO AND G.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO JOIN SDA100 H ON H.RESRCE_NO = G.RESRCE_NO AND H.SRVC_RESRCE_LCLAS_SE_CD = '01' AND H.SRVC_RESRCE_MLSFC_SE_CD = '0111' WHERE A.LINK_TYPE_SE_CD = '07' AND E.CASE_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND T.CTPV_CD LIKE #{CTPV_CD} || '%' AND T.SGG_CD LIKE #{SGG_CD} || '%' AND A.MEDIAA_SCHL_SE_CD LIKE #{ACBG} || '%' AND A.GRADE_SE_CD LIKE #{GRADE} || '%' AND D.TRPR_CHAR_SE_CD LIKE #{TRPR_SE} || '%'
/*ROW NUM 첫번째항목만 출력*/ AND F0.RN = 1
AND T.INST_NO LIKE #{INST_NO} || '%'
GROUP BY A.LINK_TYPE_SE_CD
UNION ALL
SELECT A.LINK_TYPE_SE_CD , COUNT(
DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '1' AND A.SXDC_SE_CD = 'M' THEN A.TRPR_INFO_NO END ) AS SCHBOY_MAN ,COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '1' AND A.SXDC_SE_CD = 'F' THEN A.TRPR_INFO_NO END ) AS SCHBOY_WOMAN , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '1' AND A.SXDC_SE_CD = 'X' THEN A.TRPR_INFO_NO END ) AS SCHBOY_NO_ANSWER , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '1' THEN A.TRPR_INFO_NO END ) AS SCHBOY_SUM , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '2' AND A.SXDC_SE_CD = 'M' THEN A.TRPR_INFO_NO END ) AS MSKLSD_MAN , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '2' AND A.SXDC_SE_CD = 'F' THEN A.TRPR_INFO_NO END )AS MSKLSD_WOMAN , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '2' AND A.SXDC_SE_CD = 'X' THEN A.TRPR_INFO_NO END ) AS MSKLSD_NO_ANSWER , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '2' THEN A.TRPR_INFO_NO END ) AS MSKLSD_SUM , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '3' AND A.SXDC_SE_CD = 'M' THEN A.TRPR_INFO_NO END ) AS HGSCHS_MAN , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '3' AND A.SXDC_SE_CD = 'F' THEN A.TRPR_INFO_NO END ) AS HGSCHS_WOMAN , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '3' AND A.SXDC_SE_CD = 'X' THEN A.TRPR_INFO_NO END ) AS HGSCHS_NO_ANSWER , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '3' THEN A.TRPR_INFO_NO END ) AS HGSCHS_SUM
FROM ACA400 A JOIN ( SELECT RCPT_YMD , RCPT_TRPR_INFO_NO , RCPT_INST_NO , LINK_TYPE_SE_CD , DEL_YN , ROW_NUMBER() OVER(PARTITION BY SRVC_PVSN_RQST_NO ORDER BY RCPT_SN DESC) AS RN FROM SEB420 ) B ON A.TRPR_INFO_NO = B.RCPT_TRPR_INFO_NO AND A.LINK_TYPE_SE_CD = B.LINK_TYPE_SE_CD AND B.DEL_YN = 'N' AND B.RN = 1 JOIN SAA000 T ON T.INST_NO = B.RCPT_INST_NO JOIN ACA200 D ON D.TRPR_INFO_NO = A.TRPR_INFO_NO AND D.DGNSS_EXMN_MNG_NO = A.DGNSS_EXMN_MNG_NO JOIN SEB100 E ON D.CASE_MNG_NO = E.CASE_MNG_NO AND D.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO LEFT JOIN ( SELECT CASE_MNG_NO , CASE_MNG_ODRNO , CASE_PIC_NO , PIC_INST_NO , ROW_NUMBER() OVER(PARTITION BY CASE_MNG_NO, CASE_MNG_ODRNO ORDER BY CASE_MNG_NO, CASE_MNG_ODRNO) AS RN FROM SEB150 ) F0 ON E.CASE_MNG_NO = F0.CASE_MNG_NO AND E.CASE_MNG_ODRNO = F0.CASE_MNG_ODRNO JOIN (SELECT DISTINCT RESRCE_NO , CASE_MNG_NO , CASE_MNG_ODRNO FROM SEB510 ) G ON G.CASE_MNG_NO = E.CASE_MNG_NO AND G.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO JOIN SDA100 H ON H.RESRCE_NO = G.RESRCE_NO AND H.SRVC_RESRCE_LCLAS_SE_CD = '01' AND H.SRVC_RESRCE_MLSFC_SE_CD = '0111'
WHERE A.LINK_TYPE_SE_CD IN ('08','09') AND E.CASE_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND T.CTPV_CD LIKE '%' || #{CTPV_CD} AND T.SGG_CD LIKE '%' || #{SGG_CD} AND D.MEDIAA_SCHL_SE_CD LIKE '%' || #{ACBG} AND A.GRADE_SE_CD LIKE '%' || #{GRADE} AND D.TRPR_CHAR_SE_CD LIKE '%' || #{TRPR_SE}
/*ROW NUM 첫번째항목만 출력*/ AND F0.RN = 1
AND T.INST_NO LIKE #{INST_NO} || '%'
GROUP BY A.LINK_TYPE_SE_CD
UNION ALL
SELECT D.LINK_TYPE_SE_CD , COUNT(
DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '1' AND B.SXDC_SE_CD = 'M' THEN D.TRPR_INFO_NO END ) AS SCHBOY_MAN ,COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '1' AND B.SXDC_SE_CD = 'F' THEN D.TRPR_INFO_NO END ) AS SCHBOY_WOMAN , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '1' AND B.SXDC_SE_CD = 'X' THEN D.TRPR_INFO_NO END ) AS SCHBOY_NO_ANSWER , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '1' THEN D.TRPR_INFO_NO END ) AS SCHBOY_SUM , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '2' AND B.SXDC_SE_CD = 'M' THEN D.TRPR_INFO_NO END ) AS MSKLSD_MAN , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '2' AND B.SXDC_SE_CD = 'F' THEN D.TRPR_INFO_NO END )AS MSKLSD_WOMAN , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '2' AND B.SXDC_SE_CD = 'X' THEN D.TRPR_INFO_NO END ) AS MSKLSD_NO_ANSWER , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '2' THEN D.TRPR_INFO_NO END ) AS MSKLSD_SUM , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '3' AND B.SXDC_SE_CD = 'M' THEN D.TRPR_INFO_NO END ) AS HGSCHS_MAN , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '3' AND B.SXDC_SE_CD = 'F' THEN D.TRPR_INFO_NO END ) AS HGSCHS_WOMAN , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '3' AND B.SXDC_SE_CD = 'X' THEN D.TRPR_INFO_NO END ) AS HGSCHS_NO_ANSWER , COUNT( DISTINCTCASE WHEN D.MEDIAA_SCHL_SE_CD = '3' THEN D.TRPR_INFO_NO END ) AS HGSCHS_SUM
FROM ACA200 D JOIN SEB100 C ON D.CASE_MNG_NO = C.CASE_MNG_NO AND D.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO LEFT JOIN ( SELECT CASE_MNG_NO , CASE_MNG_ODRNO , CASE_PIC_NO , PIC_INST_NO , ROW_NUMBER() OVER(PARTITION BY CASE_MNG_NO, CASE_MNG_ODRNO ORDER BY CASE_MNG_NO, CASE_MNG_ODRNO) AS RN FROM SEB150 ) F0 ON C.CASE_MNG_NO = F0.CASE_MNG_NO AND C.CASE_MNG_ODRNO = F0.CASE_MNG_ODRNO JOIN SEA200 B ON C.TRPR_INFO_NO = B.TRPR_INFO_NO JOIN SAA000 T ON F0.PIC_INST_NO = T.INST_NO LEFT JOIN ( SELECT A.* ,ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY B.ADDTNG_MNG_VALUE1 DESC, A.MNG_SN DESC) AS RN FROM SEA230 A LEFT JOIN SAC100 B ON CMMNS_CD_ID = 'ACBG_SE_CD' AND CMMNS_CD_VALUE = A.ACBG_SE_CD WHERE A.DEL_YN != 'Y' ) F /* 학력상태 */ ON F.RN = 1 AND F.TRPR_INFO_NO = C.TRPR_INFO_NO JOIN (SELECT DISTINCT RESRCE_NO , CASE_MNG_NO , CASE_MNG_ODRNO FROM SEB510 ) J ON J.CASE_MNG_NO = C.CASE_MNG_NO AND J.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO JOIN SDA100 K ON K.RESRCE_NO = J.RESRCE_NO AND K.SRVC_RESRCE_LCLAS_SE_CD = '01' AND K.SRVC_RESRCE_MLSFC_SE_CD = '0111'
WHERE D.LINK_TYPE_SE_CD IN ('10') AND C.CASE_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND T.CTPV_CD LIKE '%' || #{CTPV_CD} AND T.SGG_CD LIKE '%' || #{SGG_CD} AND D.MEDIAA_SCHL_SE_CD LIKE '%' || #{ACBG} AND F.GRADE_SE_CD LIKE '%' || #{GRADE} AND D.TRPR_CHAR_SE_CD LIKE '%' || #{TRPR_SE}
/*ROW NUM 첫번째항목만 출력*/ AND F0.RN = 1
AND T.INST_NO LIKE #{INST_NO} || '%'
GROUP BY D.LINK_TYPE_SE_CD ) )
UNION ALL
SELECT '11' AS LINK_TYPE_SE_CD , SUM(NVL(ELESCH_STDENT_MALE_NOPE, 0) + NVL(ELESCH_OSCHL_MALE_NOPE, 0)) AS SCHBOY_MAN , SUM(NVL(ELESCH_STDENT_FEMALE_NOPE, 0) + NVL(ELESCH_OSCHL_FEMALE_NOPE, 0)) AS SCHBOY_WOMAN , SUM(0) AS SCHBOY_NO_ANSWER , SUM(NVL(ELESCH_STDENT_MALE_NOPE, 0) + NVL(ELESCH_STDENT_FEMALE_NOPE, 0) + NVL(ELESCH_OSCHL_MALE_NOPE, 0) + NVL(ELESCH_OSCHL_FEMALE_NOPE, 0)) AS SCHBOY_SUM , SUM(NVL(MSKUL_STDENT_MALE_NOPE, 0) + NVL(MSKUL_OSCHL_MALE_NOPE, 0)) AS MSKLSD_MAN , SUM(NVL(MSKUL_STDENT_FEMALE_NOPE, 0) + NVL(MSKUL_OSCHL_FEMALE_NOPE, 0)) AS MSKLSD_WOMAN , SUM(0) AS MSKLSD_NO_ANSWER , SUM(NVL(MSKUL_STDENT_MALE_NOPE, 0) + NVL(MSKUL_STDENT_FEMALE_NOPE, 0) + NVL(MSKUL_OSCHL_MALE_NOPE, 0) + NVL(MSKUL_OSCHL_FEMALE_NOPE, 0)) AS MSKLSD_SUM , SUM(NVL(HGSCHL_STDENT_MALE_NOPE, 0) + NVL(HGSCHL_OSCHL_MALE_NOPE, 0)) AS HGSCHS_MAN , SUM(NVL(HGSCHL_STDENT_FEMALE_NOPE, 0) + NVL(HGSCHL_OSCHL_FEMALE_NOPE, 0)) AS HGSCHS_WOMAN , SUM(0) AS HGSCHS_NO_ANSWER , SUM(NVL(HGSCHL_STDENT_MALE_NOPE, 0) + NVL(HGSCHL_STDENT_FEMALE_NOPE, 0) + NVL(HGSCHL_OSCHL_MALE_NOPE, 0) + NVL(HGSCHL_OSCHL_FEMALE_NOPE, 0)) AS HGSCHS_SUM , SUM( NVL(A.ELESCH_STDENT_MALE_NOPE, 0) + NVL(A.MSKUL_STDENT_MALE_NOPE, 0) + NVL(A.HGSCHL_STDENT_MALE_NOPE, 0) + NVL(A.UNIVA_STDENT_MALE_NOPE, 0) + NVL(A.ELESCH_OSCHL_MALE_NOPE, 0) + NVL(A.MSKUL_OSCHL_MALE_NOPE, 0) + NVL(A.HGSCHL_OSCHL_MALE_NOPE, 0) + NVL(A.UNIVA_OSCHL_MALE_NOPE, 0) + NVL(A.AGRDHS_IOCPTN_MALE_NOPE, 0) + NVL(A.AGRDHS_EMPYMN_MALE_NOPE, 0) + NVL(A.PARNTS_PRTCR_MALE_NOPE, 0) + NVL(A.PEPL_MALE_NOPE, 0)
) + NVL(SUM(D.CNT), 0) AS SUM_MAN , SUM( NVL(A.ELESCH_STDENT_FEMALE_NOPE, 0) + NVL(A.MSKUL_STDENT_FEMALE_NOPE, 0) + NVL(A.HGSCHL_STDENT_FEMALE_NOPE, 0) + NVL(A.UNIVA_STDENT_FEMALE_NOPE, 0) + NVL(A.ELESCH_OSCHL_FEMALE_NOPE, 0) + NVL(A.MSKUL_OSCHL_FEMALE_NOPE, 0) + NVL(A.HGSCHL_OSCHL_FEMALE_NOPE, 0) + NVL(A.UNIVA_OSCHL_FEMALE_NOPE, 0) + NVL(A.AGRDHS_IOCPTN_FEMALE_NOPE, 0) + NVL(A.AGRDHS_EMPYMN_FEMALE_NOPE, 0) + NVL(A.PARNTS_PRTCR_FEMALE_NOPE, 0) + NVL(A.PEPL_FEMALE_NOPE, 0) ) + NVL(SUM(E.CNT), 0) AS SUM_WOMAN , NVL(SUM(F.CNT),0) AS SUM_NO_ANSWER FROM SED100 A JOIN ( SELECT AA.UNREGI_CASE_NO , AA.SRVC_EXCN_BIZ_NO , AA.DEL_YN , ROW_NUMBER() OVER(PARTITION BY AA.UNREGI_CASE_NO ORDER BY AA.UNREGI_CASE_NO) AS RN FROM SED110 AA JOIN SDA420 BB ON AA.SRVC_EXCN_BIZ_NO = BB.SRVC_EXCN_BIZ_NO WHERE BB.SRVC_BIZ_NO = (SELECT ADDTNG_MNG_VALUE1 FROM SAC100 WHERE CMMNS_CD_ID = 'INTNET_SMRTP_STATS_SE_CD' AND CMMNS_CD_VALUE = '01') AND DEL_YN = 'N' ) B ON A.UNREGI_CASE_NO = B.UNREGI_CASE_NO AND RN = 1 JOIN SAA000 T ON A.PIC_INST_NO = T.INST_NO LEFT JOIN ( SELECT AA.UNREGI_CASE_NO , COUNT(*) AS CNT FROM SED103 AA JOIN SEB100 BB ON AA.CASE_MNG_NO = BB.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = BB.CASE_MNG_ODRNO JOIN SEA200 CC ON BB.TRPR_INFO_NO = CC.TRPR_INFO_NO WHERE AA.CASE_MNG_NO = BB.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = BB.CASE_MNG_ODRNO AND AA.DEL_YN = 'N' AND CC.SXDC_SE_CD = 'M' GROUP BY AA.UNREGI_CASE_NO ) D ON D.UNREGI_CASE_NO = A.UNREGI_CASE_NO LEFT JOIN ( SELECT AA.UNREGI_CASE_NO , COUNT(*) AS CNT FROM SED103 AA JOIN SEB100 BB ON AA.CASE_MNG_NO = BB.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = BB.CASE_MNG_ODRNO JOIN SEA200 CC ON BB.TRPR_INFO_NO = CC.TRPR_INFO_NO WHERE AA.CASE_MNG_NO = BB.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = BB.CASE_MNG_ODRNO AND AA.DEL_YN = 'N' AND CC.SXDC_SE_CD = 'F' GROUP BY AA.UNREGI_CASE_NO ) E ON E.UNREGI_CASE_NO = A.UNREGI_CASE_NO LEFT JOIN ( SELECT AA.UNREGI_CASE_NO , COUNT(*) AS CNT FROM SED103 AA JOIN SEB100 BB ON AA.CASE_MNG_NO = BB.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = BB.CASE_MNG_ODRNO JOIN SEA200 CC ON BB.TRPR_INFO_NO = CC.TRPR_INFO_NO WHERE AA.CASE_MNG_NO = BB.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = BB.CASE_MNG_ODRNO AND AA.DEL_YN = 'N' AND CC.SXDC_SE_CD = 'X' GROUP BY AA.UNREGI_CASE_NO ) F ON F.UNREGI_CASE_NO = A.UNREGI_CASE_NO WHERE A.SRVC_RESRCE_LCLAS_SE_CD = '01' AND A.SRVC_RESRCE_MLSFC_SE_CD = '0111' AND A.SPRT_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND T.CTPV_CD LIKE #{CTPV_CD} || '%' AND T.SGG_CD LIKE #{SGG_CD} || '%'
/*종사자*/ AND A.PIC_NO = #{ENFSN_NO}
AND T.INST_NO LIKE #{INST_NO} || '%'
) B ON A.LINK_TYPE_SE_CD = B.LINK_TYPE_SE_CD
GROUP BY ROLLUP(A.LINK_TYPE_SE_CD)
ORDER BY A.LINK_TYPE_SE_CD

if.if:
AND (   D.BEFFAT_INTNET_DGNSS_SE_CD#{LEVEL}
    AND D.BEFFAT_SMRTP_DGNSS_SE_CD#{LEVEL}
    AND D.BEFFAT_GAMBLE_DGNSS_SE_CD#{LEVEL}
    )

AND (   D.BEFFAT_INTNET_DGNSS_SE_CD#{LEVEL}
    OR  D.BEFFAT_SMRTP_DGNSS_SE_CD#{LEVEL}
    OR  D.BEFFAT_GAMBLE_DGNSS_SE_CD#{LEVEL}
    )
